INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'creando-palabras-con-globos', 'Creando Palabras con Globos', 'Dinámica de agilidad verbal y coordinación inflable donde los scouts inventan términos originales sin dejar caer el globo.', '<h2>📜 Descripción de Creando Palabras con Globos</h2>
<p><b>Creando Palabras con Globos</b> es una dinámica scout de rapidez mental, vocabulario inventivo y destreza física. En esta prueba cooperativa, cada patrulla se organiza en un pequeño círculo manteniendo un globo inflado en el aire mediante suaves toques de mano, cabeza o rodilla. Cada vez que un scout golpea el globo hacia un compañero, debe pronunciar en voz alta una palabra totalmente inventada (ej. <i>''Zulipampa''</i>, <i>''Cromaflor''</i> o <i>''Kinesaurio''</i>) junto con su significado improvisado en una sola frase antes de que el globo toque el suelo.</p>
<p>Esta actividad ejercita la soltura léxica, el pensamiento divergente y la agilidad muscular en Manada, Compañía, Tropa, Avanzada y Clan.</p>

<h2>🎲 ¿Cómo se juega Creando Palabras con Globos?</h2>
<p>Para llevar a cabo la dinámica con solemnidad y alegría, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Formación del Círculo:</b> Las patrullas forman círculos de 4 a 6 participantes sosteniendo un globo inflado.</li>
  <li><b>Saque de Neologismos:</b> El primer jugador lanza el globo hacia arriba pronunciando su primera palabra inventada.</li>
  <li><b>Mantención y Significado:</b> El scout que recibe debe tocar el globo hacia otro par declarando el significado de la palabra anterior o creando una nueva.</li>
  <li><b>Prohibición de Repetición:</b> Queda prohibido repetir palabras de diccionarios reales o términos ya dichos en la ronda.</li>
  <li><b>Conteo de Toques:</b> La patrulla suma 1 punto por cada pase con palabra inventada exitosa sostenida en el aire.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de Creando Palabras con Globos</h2>
<p>La actividad valora la creatividad léxica y la destreza en el Tally:</p>
<ul>
  <li><b>Mayor Originalidad Lingüística:</b> Otorgar 5 puntos al equipo con las creaciones de palabras más ingeniosas y divertidas.</li>
  <li><b>Récord de Pases Continuos:</b> Otorgar 3 puntos a la patrulla que mantenga el globo en el aire durante más tiempo.</li>
  <li><b>Trabajo Cooperativo:</b> Otorgar 3 puntos a la unidad que integre equitativamente los toques entre todos sus miembros.</li>
</ul>', '/uploads/creando-palabras-con-globos.webp', 'publicado', '{"areas": ["creatividad", "sociabilidad"], "unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Globos"], "objetivos": ["Estimular la creatividad", "Estimular la agilidad mental", "Fomentar la comunicación e interpretación", "Trabajo en equipo"], "justificacion_areas": "Creando Palabras con Globos potencia la creatividad al desafiar el pensamiento lateral e incentive la invención de neologismos y construcciones idiomáticas sin juzgamiento. Desarrolla la sociabilidad al afianzar el soporte mutuo, el ritmo colectivo y la risa compartida desde Manada hasta Clan.", "variaciones": "<b>Diccionario Scout Neológico:</b> Registrar en un cuaderno de patrulla las 10 mejores palabras inventadas para el Tally.<br><b>Globos Gigantes en Parejas:</b> Realizar los toques sujetados de las manos en duplas.<br><b>Edición Definiciones Absurdas:</b> Un scout dice la palabra inventada y su receptor define el uso scout de dicha palabra.", "recomendaciones": "Tener globos de repuesto por si alguno se revienta. Fomentar un ambiente relajado donde no exista el miedo al error de pronunciación.", "objetivos_educativos": [{"id": "897408de-c314-4908-aee0-4a0e0e56d4ba", "area": "Creatividad", "unidad": "Manada", "texto": "Converso con los demás sobre las cosas que me llaman la atención.", "como_se_cumple": "Compartiendo con entusiasmo la invención de nuevas palabras en el equipo."}, {"id": "47e7e2d8-12cd-447d-8df4-251e83aa547b", "area": "Creatividad", "unidad": "Manada", "texto": "Trato de hablar claro y conocer nuevas palabras.", "como_se_cumple": "Pronunciando con claridad y fluidez los neologismos inventados durante el pase del globo."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Respetando las normas de no repetir palabras y coordinar los toques."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Apoyando al compañero cuando se le dificulte encontrar un neologismo."}, {"id": "0d742d23-ebe1-40e6-97df-37bc03edb010", "area": "Creatividad", "unidad": "Compañía", "texto": "Expreso mis pensamientos y experiencias en el Tally.", "como_se_cumple": "Expresando vocablos y definiciones originales en la bitácora de patrulla."}, {"id": "6e910d1c-7021-49a5-9ece-637f480a1ec7", "area": "Creatividad", "unidad": "Compañía", "texto": "Expreso por distintos medios mis intereses y aptitudes artísticas.", "como_se_cumple": "Conectando significados ingeniosos y construcciones idiomáticas en milisegundos."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Favoreciendo el ambiente de aliento y risa sana en la patrulla."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Promoviendo la desinhibición y el disfrute compartido sin discriminación."}, {"id": "981fa19b-7f60-4e0e-b2fa-16123df5e37e", "area": "Creatividad", "unidad": "Tropa", "texto": "Expreso mis pensamientos y experiencias en el Tally.", "como_se_cumple": "Organizando estrategias de pases para maximizar los neologismos."}, {"id": "9758e4f9-728b-4435-a8a3-11fd36c5e3be", "area": "Creatividad", "unidad": "Tropa", "texto": "Expreso por distintos medios mis intereses y aptitudes artísticas.", "como_se_cumple": "Asociando ideas y términos abstractos en milisegundos ante la Tropa."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Fomentando la cooperación activa y la escucha atenta de las definiciones."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Fortaleciendo la fraternidad e inclusión entre todos los miembros."}, {"id": "ed17d59c-1c64-4080-a206-bbe72eeae5a4", "area": "Creatividad", "unidad": "Avanzada", "texto": "Expresa lo que piensa y siente a través de distintos medios, creando en los ambientes en que actúa espacios gratos que faciliten el encuentro y el perfeccionamiento entre las personas.", "como_se_cumple": "Promoviendo la creación lingüística y el pensamiento lateral en la Avanzada."}, {"id": "3fd19eb4-737c-43c5-9ea8-5e5307ce0309", "area": "Sociabilidad", "unidad": "Avanzada", "texto": "Cumple las normas que la sociedad se ha dado, evaluándolas con responsabilidad y sin renunciar a cambiarlas.", "como_se_cumple": "Liderando dinámicas de desinhibición y cohesión responsable."}, {"id": "91e60eba-e267-4d1a-b27b-ef61a7b03b31", "area": "Creatividad", "unidad": "Clan", "texto": "Expresa lo que piensa y siente a través de distintos medios, creando en los ambientes en que actúa espacios gratos que faciliten el encuentro y el perfeccionamiento entre las personas.", "como_se_cumple": "Ejercitando la soltura de expresión y la innovación artística en el Clan Rover."}, {"id": "b5954f1c-4d0d-4bdb-97d8-821583beb77e", "area": "Sociabilidad", "unidad": "Clan", "texto": "Cumple las normas que la sociedad se ha dado, evaluándolas con responsabilidad y sin renunciar a cambiarlas.", "como_se_cumple": "Desarrollando la camaradería, el servicio alegre y la hermandad scout."}]}'::jsonb, NOW(), NOW(), NUL